function queryParamList(n,t,i){var r=null;return $.ajax({async:!1,url:"/WeixinService/business/queryParamList.xhtml",data:{paramType:n,paramKey:t,pmValueOne:i},dataType:"json",cache:!1,type:"POST",error:function(){show_tips("网络繁忙，请稍后再试。")},success:function(n){n!=null&&n.resultCode=="0000"&&(r=n.data)}}),r}function updateCmfUserBaseInfo(){var n=$("#voccode").val(),t=$.trim($("#otherVocation").val());if(n=="15"&&t==""){errorRemark("请填写您的职业");return}n!="15"&&(t="");$.ajax({async:!1,url:"/WeixinService/business/updateCmfUserBaseInfo.xhtml",data:{nation:"",province:"",city:"",addr:"",voccode:n,birthDate:"",taxResidentType:"",otherVocation:t},dataType:"json",cache:!1,type:"POST",error:function(){errorRemark("网络繁忙，请稍后再试。")},success:function(n){n!=null&&n.resultCode=="0000"?window.location.href="/WeixinService/business/user/userInfo.shtml":errorRemark("选择职业失败")}})}function queryUserinfo(){$.ajax({async:!1,url:"/WeixinService/business/queryUserinfo.xhtml",data:"",dataType:"json",cache:!1,type:"post",error:function(){errorRemark("网络繁忙，请稍后再试。")},success:function(n){n.returnCode!=null&&n.returnCode=="0000"&&$("#otherVocation").val(n.otherVocation)}})}function showPop(){$("#recommendPop").show();$(".backLayer").show()}function closePop(){$("#recommendPop").hide();$(".backLayer").hide()}function ischinese(n){return/^[\u4e00-\u9fa5]+$/.test(n)}$(document).ready(function(){var i,r,n,t;for(queryUserinfo(),$(".header .top-a h2").html("选择职业"),document.title="选择职业",i=queryParamList("SYSTEM","VOCCODE",""),r="",n=0;n<i.length;n++)t=i[n],r+='<a class="href-point" data-value="'+t.pmco+'" data-text="'+t.pmnm+'">'+t.pmnm+'<i id="area"><\/i><\/a>';$("#section_01 .center-accountset").html(r);$("#section_01 a.href-point").click(function(){var n=$(this).data("value");if($("#voccode").val(n),n=="15"){showPop();return}updateCmfUserBaseInfo()})})